     "mota": "ingurunea",
     "izena": "Teorema",
     "kolorea": "urdina",
     "etzana": true,
     "titulua": null,
     "blokeak": [
      {
       "mota": "testua",
       "html": "<math display=\"inline\"><mi>n</mi></math> ordenako ekuazio lineal homogeneo baten <math display=\"inline\"><mi>n</mi></math> soluzio <math display=\"inline\"><msub><mi>y</mi><mi>k</mi></msub></math> linealki independente emanda, beste edozein soluzio era bakarrean adieraz daiteke soluzio horien koefiziente konstanteetako konbinazio lineal gisa."
      }
     ]
